SELECT business_id, project_id, task_id, expert_run_id, version,
storage_key, file_name, media_type, size_bytes, sha256, status
FROM digital_team_project_artifact WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND business_id = #{id}

SELECT business_id, project_id, task_id, expert_run_id, version,
storage_key, file_name, media_type, size_bytes, sha256, status
FROM digital_team_project_artifact WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND storage_key = #{storageKey}

SELECT storage_key FROM digital_team_project_artifact
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND business_id = #{reference} AND status = 'AVAILABLE'

SELECT COUNT(*) FROM digital_team_project_artifact WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND task_id = #{coordinatorTaskId}
AND expert_run_id = #{agentRunId} AND business_id = #{artifactId}
AND status = 'AVAILABLE'

SELECT a.storage_key FROM digital_team_project_artifact a JOIN digital_team_coordinator_task t ON t.business_id = a.task_id WHERE t.plan_id = #{planId} AND t.task_key IN
#{item}
AND a.status = 'AVAILABLE' ORDER BY a.business_id

SELECT business_id AS id, task_id, version, file_name, media_type, size_bytes, sha256, status
FROM digital_team_project_artifact WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
ORDER BY created_at
